function isDigits(s) {
  if (s.length === 0) {
    return false;
  }
  for (var i = 0; i < s.length; i++) {
    var c = s.charAt(i);
    if (c < "0" || c > "9") {
      return false;
    }
  }
  return true;
}

console.log(isDigits("12345"), isDigits("12a45"), isDigits(""));

